import app from 'flarum/forum/app';
import classList from 'flarum/common/utils/classList';
export function avatarUrl(user) {
  return user?.avatarUrl || user?.avatar_url || null;
}
export function userInitial(user) {
  return String(user?.displayName || user?.display_name || user?.username || '?').slice(0, 1).toUpperCase();
}
export function userColor(user) {
  const name = String(user?.username || 'social');
  let hash = 0;
  for (let i = 0; i < name.length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash);
  const hue = Math.abs(hash) % 360;
  return `hsl(${hue}, 48%, 46%)`;
}
export function Avatar(user, size = 36) {
  return m('span', {
    className: classList('SocialAvatar', `SocialAvatar--${size}`),
    style: avatarUrl(user) ? {
      backgroundImage: `url("${avatarUrl(user)}")`
    } : {
      background: userColor(user)
    },
    title: user?.displayName || user?.display_name || user?.username
  }, avatarUrl(user) ? null : userInitial(user));
}
export function formatBody(body, bodyHtml) {
  if (!body) return [];
  if (bodyHtml) {
    return [m('div', {
      className: 'Social-richText'
    }, m.trust(bodyHtml))];
  }
  const nodes = [];
  const regex = /(https?:\/\/[^\s<]+|#[\p{L}\p{N}_]+|@[A-Za-z0-9_.-]{2,30})/gu;
  let lastIndex = 0;
  let match;
  while ((match = regex.exec(body)) !== null) {
    pushText(nodes, body.slice(lastIndex, match.index));
    const token = match[0];
    if (token.startsWith('http')) {
      nodes.push(m('a', {
        href: token,
        target: '_blank',
        rel: 'noopener noreferrer nofollow',
        className: 'Social-link'
      }, token.replace(/^https?:\/\//, '').slice(0, 80)));
    } else if (token.startsWith('#')) {
      nodes.push(m('a', {
        href: app.route('social.explore', {
          hashtag: token.slice(1)
        }),
        className: 'Social-hashtag',
        'data-hashtag': token.slice(1)
      }, token));
    } else {
      nodes.push(m('a', {
        href: app.route('social.profile', {
          username: token.slice(1)
        }),
        className: 'Social-mention'
      }, token));
    }
    lastIndex = regex.lastIndex;
  }
  pushText(nodes, body.slice(lastIndex));
  return nodes;
}
function pushText(nodes, text) {
  if (!text) return;
  text.split('\n').forEach((line, index) => {
    if (index > 0) nodes.push(m('br'));
    if (line) nodes.push(line);
  });
}
export function timeAgo(value) {
  if (!value) return '';
  const date = new Date(value);
  const seconds = Math.round((Date.now() - date.getTime()) / 1000);
  const future = seconds < -45;
  const distance = Math.abs(seconds);
  if (distance < 45) return app.translator.trans('cengizkemec-social.forum.time.just_now');
  const key = distance < 3600 ? 'minutes' : distance < 86400 ? 'hours' : distance < 604800 ? 'days' : null;
  if (key === 'minutes') {
    return app.translator.trans(`cengizkemec-social.forum.time.${future ? 'in_' : ''}minutes`, {
      count: Math.max(1, Math.round(distance / 60))
    });
  }
  if (key === 'hours') {
    return app.translator.trans(`cengizkemec-social.forum.time.${future ? 'in_' : ''}hours`, {
      count: Math.max(1, Math.round(distance / 3600))
    });
  }
  if (key === 'days') {
    return app.translator.trans(`cengizkemec-social.forum.time.${future ? 'in_' : ''}days`, {
      count: Math.max(1, Math.round(distance / 86400))
    });
  }
  return date.toLocaleDateString(app.data.locale || undefined);
}
export function promptLogin(reason = 'generic') {
  if (app.session.user) return false;
  app.modal.show(() => import(/* webpackChunkName: 'forum/components/GuestPromptModal', webpackMode: 'lazy-once' */ './components/GuestPromptModal'), {
    reason
  });
  return true;
}
export function openUser(user) {
  return app.route('social.profile', {
    username: user?.username || ''
  });
}
export function roomUrl(room) {
  return app.route('social.room', {
    slug: room?.slug || room?.id
  });
}
export function channelUrl(channel) {
  return app.route('social.channel', {
    id: channel?.slug || channel?.id
  });
}
export function roomCapacityLabel(room) {
  const count = Number(room?.participantCount) || 0;
  const capacity = Number(room?.capacity) || 0;
  return capacity > 0 ? `${count} / ${capacity}` : `${count} / ∞`;
}
export function handleApiError(error) {
  app.alerts.show({
    type: 'error'
  }, error?.message || app.translator.trans('cengizkemec-social.forum.errors.generic'));
}
export function username(value) {
  return value.replace(/^@/, '');
}flarum.reg.addChunkModule('213', '883', 'cengizkemec-social', 'forum/components/GuestPromptModal');